using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ───────────────────────────────────────────────
    // CalculateTotal – DataRow (compile-time constants)
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0,  20.00,  DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00,  5, 0.10, 0.00,   DisplayName = "Zero price yields zero")]
    [DataRow(99.99, 0, 0.20, 0.00,   DisplayName = "Zero quantity yields zero")]
    [DataRow(10.00, 1, 1.0,  20.00,  DisplayName = "100% tax doubles the price")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ───────────────────────────────────────────────
    // CalculateTotal – DynamicData (decimal precision & edge cases)
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> CalculateTotalEdgeCases
    {
        get
        {
            yield return [100.005m,  1,  0.00m,  100.005m,   "High-precision unit price"];
            yield return [9999.99m,  100, 0.25m, 1249998.75m, "Large quantity with tax"];
            yield return [0.01m,     1,  0.07m,  0.0107m,     "Penny with 7% tax"];
        }
    }

    [TestMethod]
    [DynamicData(nameof(CalculateTotalEdgeCases))]
    public void CalculateTotal_EdgeCases_ReturnsExpected(
        decimal unitPrice, int quantity, decimal taxRate, decimal expected, string scenario)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expected, result, $"Failed for: {scenario}");
    }

    // ───────────────────────────────────────────────
    // CalculateTotal – invalid inputs throw
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.0, 1,  0.10, "unitPrice",  DisplayName = "Negative unit price")]
    [DataRow(10.0, -1, 0.10, "quantity",   DisplayName = "Negative quantity")]
    [DataRow(10.0, 1,  -0.1, "taxRate",    DisplayName = "Negative tax rate")]
    [DataRow(10.0, 1,  1.01, "taxRate",    DisplayName = "Tax rate above 1")]
    public void CalculateTotal_WithInvalidInputs_Throws(
        double unitPrice, int quantity, double taxRate, string expectedParamName)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // ───────────────────────────────────────────────
    // ApplyDiscount – DataRow
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(100.00, 0.0,   100.00, DisplayName = "0% discount – no change")]
    [DataRow(100.00, 10.0,  90.00,  DisplayName = "10% discount")]
    [DataRow(100.00, 50.0,  50.00,  DisplayName = "50% discount")]
    [DataRow(100.00, 100.0, 0.00,   DisplayName = "100% discount – free")]
    [DataRow(49.99,  25.0,  37.4925, DisplayName = "Fractional result")]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        double price, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    // ───────────────────────────────────────────────
    // ApplyDiscount – DynamicData from method source
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> DiscountEdgeCases()
    {
        yield return [0.00m,    50.0m,  0.00m,         "Zero price stays zero"];
        yield return [1000.00m, 33.33m, 666.70m,       "Recurring decimal discount"];
        yield return [0.01m,    99.0m,  0.0001m,       "Penny with 99% discount"];
    }

    [TestMethod]
    [DynamicData(nameof(DiscountEdgeCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_EdgeCases_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result, $"Failed for: {scenario}");
    }

    // ───────────────────────────────────────────────
    // ApplyDiscount – invalid discount throws
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(100.0, -1.0,  DisplayName = "Negative discount")]
    [DataRow(100.0, 100.1, DisplayName = "Discount above 100%")]
    public void ApplyDiscount_WithInvalidDiscount_Throws(double price, double discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent));
    }
}

